-- NEW-CHK-012: private checklist photo/file/signature evidence.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('checklist-evidence','checklist-evidence',false,10485760,array['application/pdf','image/png','image/jpeg','image/webp'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create function public.ftf_record_checklist_execution_evidence(p_organisation_id uuid,p_actor_internal_user_id uuid,p_execution_id uuid,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare e public.checklist_executions%rowtype;v public.checklist_execution_evidence%rowtype;begin
 if not public.ftf_actor_has_permission(p_organisation_id,p_actor_internal_user_id,'compliance.manage')then return jsonb_build_object('forbidden',true);end if;select*into e from public.checklist_executions where organisation_id=p_organisation_id and id=p_execution_id and status='DRAFT';if not found then return jsonb_build_object('execution_unavailable',true);end if;insert into public.checklist_execution_evidence(organisation_id,execution_id,item_id,evidence_kind,internal_file_id,file_version,original_filename,content_type,byte_size,sha256_checksum,provenance,created_by_internal_user_id)values(p_organisation_id,p_execution_id,p_payload->>'itemId',p_payload->>'evidenceKind',(p_payload->>'internalFileId')::uuid,(p_payload->>'fileVersion')::integer,p_payload->>'originalFilename',p_payload->>'contentType',(p_payload->>'sizeBytes')::bigint,p_payload->>'checksumSha256',p_payload->'provenance',p_actor_internal_user_id)returning*into v;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'checklist.evidence.recorded','checklist_execution_evidence',v.id,jsonb_build_object('executionId',p_execution_id,'itemId',v.item_id,'checksum',v.sha256_checksum));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'checklist.evidence.recorded','checklist_execution',p_execution_id,jsonb_build_object('evidenceId',v.id,'itemId',v.item_id));return jsonb_build_object('record',to_jsonb(v));end$$;
revoke all on function public.ftf_record_checklist_execution_evidence(uuid,uuid,uuid,jsonb)from public,anon,authenticated;grant execute on function public.ftf_record_checklist_execution_evidence(uuid,uuid,uuid,jsonb)to service_role;
